export function getTeamLogoUrl(teamId: string, clubName?: string): string | undefined {
  if (TEAM_LOGOS_DATA[teamId]) return TEAM_LOGOS_DATA[teamId];
  if (clubName) {
    const normalized = clubName.toLowerCase().trim();
    const matchedId = CLUB_TO_TEAM_ID[normalized];
    if (matchedId && TEAM_LOGOS_DATA[matchedId]) return TEAM_LOGOS_DATA[matchedId];
  }
  return undefined;
};
